def generate(rng):
    b = rng.randint(2, 20)
    y_bar = rng.randint(1, 25)
    a = b * y_bar
    opts = [
        {'content': f'La pendiente de la línea de fase es $f\'(\\bar{{y}}) = -{b} < 0$, lo que garantiza que el equilibrio es dinámicamente estable.', 'is_correct': True, 'distractor_id': None},
        {'content': f'Si $y > {y_bar}$, la tasa de cambio es $\\dot{{y}} < 0$, conduciendo la trayectoria de vuelta hacia el punto de equilibrio.', 'is_correct': True, 'distractor_id': None},
        {'content': f'El equilibrio es estable porque la función $f(y)$ tiene pendiente positiva $+{b} > 0$ en el punto de corte.', 'is_correct': False, 'error_rationale': 'Inversión del criterio de estabilidad de la pendiente: una pendiente positiva f\'(y) > 0 aleja las trayectorias y genera inestabilidad.', 'distractor_id': 'D-C01-01'},
        {'content': f'Dado que $\\bar{{y}} = {y_bar} > 0$, la variable $y$ siempre aumenta en el tiempo independientemente de su nivel inicial.', 'is_correct': False, 'error_rationale': 'Atribución errónea de dirección dinámica: el aumento o disminución depende del signo de \\dot{{y}}, no del nivel positivo de y.', 'distractor_id': 'D-C01-03'}
    ]
    return {
        'vars': {'a': a, 'b': b, 'y_bar': y_bar},
        'options': opts,
        'distractors': []
    }

